class Solution:
    def maximizeXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        ans = []
        for x, m in queries:
            best = -1
            for v in nums:
                if v <= m and (v ^ x) > best:
                    best = v ^ x
            ans.append(best)
        return ans

