class Solution {
public:
    vector<int> maximizeXor(vector<int>& nums, vector<vector<int>>& queries) {
        vector<int> ans;
        ans.reserve(queries.size());
        for (auto& q : queries) {
            int best = -1;
            for (int v : nums)
                if (v <= q[1] && (v ^ q[0]) > best) best = v ^ q[0];
            ans.push_back(best);
        }
        return ans;
    }
};

