class Solution {
    public int[] maximizeXor(int[] nums, int[][] queries) {
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int best = -1;
            for (int v : nums)
                if (v <= queries[i][1]) best = Math.max(best, v ^ queries[i][0]);
            ans[i] = best;
        }
        return ans;
    }
}

