class Solution:
    def maximizeXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        nums.sort()
        ordered = sorted((m, x, i) for i, (x, m) in enumerate(queries))
        ans = [-1] * len(queries)
        root = {}
        k = 0
        for m, x, i in ordered:
            while k < len(nums) and nums[k] <= m:
                node = root
                for b in range(29, -1, -1):
                    node = node.setdefault((nums[k] >> b) & 1, {})
                k += 1
            if k == 0:
                continue
            node = root
            cur = 0
            for b in range(29, -1, -1):
                bit = (x >> b) & 1
                cur <<= 1
                if 1 - bit in node:
                    cur |= 1
                    node = node[1 - bit]
                else:
                    node = node[bit]
            ans[i] = cur
        return ans

