class Solution {
    struct Node {
        Node* ch[2] = {nullptr, nullptr};
    };
public:
    vector<int> maximizeXor(vector<int>& nums, vector<vector<int>>& queries) {
        sort(nums.begin(), nums.end());
        int qn = queries.size();
        vector<int> order(qn);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(),
             [&](int a, int b) { return queries[a][1] < queries[b][1]; });
        vector<int> ans(qn, -1);
        Node* root = new Node();
        int k = 0, n = nums.size();
        for (int qi : order) {
            int x = queries[qi][0], m = queries[qi][1];
            while (k < n && nums[k] <= m) {
                Node* node = root;
                for (int b = 29; b >= 0; --b) {
                    int bit = (nums[k] >> b) & 1;
                    if (!node->ch[bit]) node->ch[bit] = new Node();
                    node = node->ch[bit];
                }
                ++k;
            }
            if (k == 0) continue;
            Node* node = root;
            int cur = 0;
            for (int b = 29; b >= 0; --b) {
                int bit = (x >> b) & 1;
                if (node->ch[1 - bit]) {
                    cur |= 1 << b;
                    node = node->ch[1 - bit];
                } else {
                    node = node->ch[bit];
                }
            }
            ans[qi] = cur;
        }
        return ans;
    }
};

