class Solution {
    static class Node {
        Node[] ch = new Node[2];
    }
    public int[] maximizeXor(int[] nums, int[][] queries) {
        Arrays.sort(nums);
        Integer[] idx = new Integer[queries.length];
        for (int i = 0; i < idx.length; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Integer.compare(queries[a][1], queries[b][1]));
        Node root = new Node();
        int k = 0, n = nums.length;
        int[] ans = new int[queries.length];
        Arrays.fill(ans, -1);
        for (int qi : idx) {
            int x = queries[qi][0], m = queries[qi][1];
            while (k < n && nums[k] <= m) {
                Node node = root;
                for (int b = 29; b >= 0; b--) {
                    int bit = (nums[k] >> b) & 1;
                    if (node.ch[bit] == null) node.ch[bit] = new Node();
                    node = node.ch[bit];
                }
                k++;
            }
            if (k == 0) continue;
            Node node = root;
            int cur = 0;
            for (int b = 29; b >= 0; b--) {
                int bit = (x >> b) & 1;
                if (node.ch[1 - bit] != null) {
                    cur |= 1 << b;
                    node = node.ch[1 - bit];
                } else {
                    node = node.ch[bit];
                }
            }
            ans[qi] = cur;
        }
        return ans;
    }
}

