var maximizeXor = function(nums, queries) {
    nums.sort((a, b) => a - b);
    const qs = queries.map((q, i) => [q[1], q[0], i]).sort((a, b) => a[0] - b[0]);
    const root = {};
    let k = 0;
    const ans = new Array(queries.length).fill(-1);
    for (const [m, x, qi] of qs) {
        while (k < nums.length && nums[k] <= m) {
            let node = root;
            for (let b = 29; b >= 0; b--) {
                const bit = (nums[k] >> b) & 1;
                if (!node[bit]) node[bit] = {};
                node = node[bit];
            }
            k++;
        }
        if (k === 0) continue;
        let node = root, cur = 0;
        for (let b = 29; b >= 0; b--) {
            const bit = (x >> b) & 1;
            cur <<= 1;
            if (node[1 - bit]) {
                cur |= 1;
                node = node[1 - bit];
            } else {
                node = node[bit];
            }
        }
        ans[qi] = cur;
    }
    return ans;
};
